'use strict';
// Insert only missing historical work orders. Existing and deleted records are never overwritten.
const {Pool}=require('pg');
const extra={date:'2026-10-15',lot:'DBJ1501',qty:50,actual:null,product:'NBA20HM05',materials:[['NMP','',7.606,null],['BYK180','',0.094,null],['AOH30','',6.565,null],['PAI 27-2','',15.084,null],['SBR','',20.651,null]]};
const rows=[{"date":"2026-08-19","lot":"DBH1901","qty":140,"actual":112,"materials":[["NMP","20251031063",34.68,34.7],["BYK180","006-8-25",0.62,0.78],["AOH30","2708935",21.82,27.1],["SBS+Pvdf","20260617PS",24.14,30],["SBR","C3026B26A(1)",35.21,43.8]]},{"date":"2026-10-06","lot":"DBJ0601","qty":140,"actual":115,"materials":[["NMP","2026011101",24.94,24],["BYK180","2708935",0.197,0.18],["AOH30","006-8-25",19.7,19.75],["Pvdf","20260506P",36.07,36.05],["SBS","20260504S",24.74,24.7],["SBR","C3026B26A(1)",34.35,34.35]]}];
rows.push(extra);
async function run(){if(!process.env.DATABASE_URL)return;const pool=new Pool({connectionString:process.env.DATABASE_URL,ssl:{rejectUnauthorized:false},max:1});let c;try{c=await pool.connect();await c.query('BEGIN');const exists=await c.query("SELECT to_regclass('public.qmes_work_order_documents') AS docs,to_regclass('public.qmes_work_order_deletions') AS deletions");if(!exists.rows[0].docs||!exists.rows[0].deletions){await c.query('ROLLBACK');return;}let inserted=0;for(const row of rows){const id='WO-'+row.date.replace(/-/g,'')+'-001';const doc={id,workDate:row.date,productionType:'일반',fields:{'작업지시번호':id,'고객사':'현대자동차','제품명':row.product||'NBA20HM05','생산 LOT NO':row.lot,'설비명':'HSM(high shear mixer)','작업자':'대리 박도훈, 주임 문지훈','계획수량':String(row.qty),'실적수량':row.actual==null?'':String(row.actual),'작업기간':row.date+' ~ '+row.date,'진행상태':'완료'},materials:row.materials.map(m=>({name:m[0],lot:m[1],plan:String(m[2]),actual:String(m[3])})),note:'원본 작업지시서 이력 등록: '+row.date+(row.actual==null?' / 실적 미기재':' / 생산실적 '+row.actual+'kg')};await c.query("UPDATE qmes_work_order_documents SET document=jsonb_set(jsonb_set(document,'{fields,고객사}',to_jsonb($2::text),true),'{fields,제품명}',to_jsonb($3::text),true),updated_at=NOW() WHERE id=$1 AND document->>'note' LIKE '원본 작업지시서 이력 등록:%' AND document->'fields'->>'생산 LOT NO'=$4 AND NOT EXISTS(SELECT 1 FROM qmes_work_order_deletions WHERE id=$1)",[id,'현대자동차',row.product||'NBA20HM05',row.lot]);const q=await c.query("INSERT INTO qmes_work_order_documents(id,document) SELECT $1,$2::jsonb WHERE NOT EXISTS(SELECT 1 FROM qmes_work_order_deletions WHERE id=$1) AND NOT EXISTS(SELECT 1 FROM qmes_work_order_documents WHERE document->'fields'->>'생산 LOT NO'=$3 OR id=$1) ON CONFLICT(id) DO NOTHING",[id,JSON.stringify(doc),row.lot]);inserted+=q.rowCount||0;}await c.query('COMMIT');console.log('[QMES AUG/OCT] inserted',inserted);}catch(e){if(c)await c.query('ROLLBACK').catch(()=>{});console.error('[QMES AUG/OCT]',e.message);}finally{if(c)c.release();await pool.end().catch(()=>{});}}
setTimeout(run,5000);
